def mi250_topology(nnode: int):
    G = nx.DiGraph()
    compute_nodes = []
    for a in range(nnode):
        for b in range(16):
            for c in range(16):
                if MI250_ADJ_MAT[b][c] > 0:
                    G.add_edge((a, "GPU", b), (a, "GPU", c), capacity=MI250_ADJ_MAT[b][c] * xGMI_BW)
