    ids = set()
    total = 0
    for b in bookings:
        if not isinstance(b, dict) or set(b.keys()) != {'id', 'owner', 'window', 'envelope'}:
            raise Invalid()
        bid = _sid(b['id'])
        owner = _sid(b['owner'])
        s, e = _window(b['window'])
        env = _envelope(b['envelope'])
        for l in env:
            if l >= len(uv):
                raise Invalid()
        if bid in ids:
            raise Invalid()
        ids.add(bid)
        total += len(env)
        bl.append((bid, owner, s, e, env))
    if total > 2048:
        raise Invalid()
    if self.loaded:
        return _err('ALREADY_LOADED', self.rev)
    for l in range(len(uv)):
        events = []
        for (bid, owner, s, e, env) in bl:
            rr = env.get(l, 0)
            if rr:
                events.append((s, rr))
                events.append((e, -rr))
        events.sort()
        cur = 0
        for (t, d) in events:
            cur += d
            if cur > cap[l]:
                raise Invalid()
    self.loaded = True
    self.n = n
    self.linkuv = uv
    self.linkcap = cap
    self.rev = 0
    self.now = 0
    self.leases = {}
    self.load_ids = set(ids)
    self.prep = {}
    for (bid, owner, s, e, env) in bl:
        self.leases[bid] = {'owner': owner, 's': s, 'e': e, 'env': dict(env), 'state': 'live'}
    return {'status': 'ok', 'rev': 0, 'now': 0}

